{name=[=[
VertexYard]=],source=[=[
local Yard = {}

local graphite = Color3.fromRGB(37, 44, 52)
local navy = Color3.fromRGB(38, 54, 66)
local concrete = Color3.fromRGB(100, 109, 113)
local titanium = Color3.fromRGB(142, 153, 154)
