	local v=make("ViewportFrame",parent,{BackgroundTransparency=1,Position=pos,Size=size,Ambient=Color3.fromRGB(180,185,200),LightColor=Color3.new(1,0.95,0.85),LightDirection=Vector3.new(-1,-2,-2)})
